import{_ as t,o as l,c as a,a2 as i}from"./chunks/framework.DaGSOal_.js";const h=JSON.parse('{"title":"Usage Guide","description":"","frontmatter":{"sidebar_position":4},"headers":[],"relativePath":"duplicate-asset-detector/usage.md","filePath":"duplicate-asset-detector/usage.md","lastUpdated":1794046641000}'),o={name:"duplicate-asset-detector/usage.md"};function s(r,e,n,c,u,p){return l(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="usage-guide" tabindex="-1">Usage Guide <a class="header-anchor" href="#usage-guide" aria-label="Permalink to &quot;Usage Guide&quot;">​</a></h1><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h2><h3 id="step-1-open-the-tool" tabindex="-1">Step 1: Open the Tool <a class="header-anchor" href="#step-1-open-the-tool" aria-label="Permalink to &quot;Step 1: Open the Tool&quot;">​</a></h3><p><strong>Method 1:</strong> Via Tools Menu</p><ol><li>Go to <strong>Tools → Duplicate Asset Detector</strong></li></ol><p><strong>Method 2:</strong> Via Context Menu</p><ol><li>Right-click any folder in Content Browser</li><li>Select <strong>Find Duplicates</strong></li></ol><h3 id="step-2-configure-scan-settings" tabindex="-1">Step 2: Configure Scan Settings <a class="header-anchor" href="#step-2-configure-scan-settings" aria-label="Permalink to &quot;Step 2: Configure Scan Settings&quot;">​</a></h3><p><strong>Basic Settings:</strong></p><ul><li>Choose scan scope (All Content or Current Folder)</li><li>Set minimum file size threshold (skip tiny assets)</li><li>Select asset types to include</li></ul><p><strong>Advanced Settings:</strong></p><ul><li>Exclude specific folder patterns</li><li>Include/exclude Engine content</li><li>Include/exclude Plugin content</li></ul><p><strong>Or use defaults</strong> - the plugin comes preconfigured with sensible settings!</p><h3 id="step-3-run-the-scan" tabindex="-1">Step 3: Run the Scan <a class="header-anchor" href="#step-3-run-the-scan" aria-label="Permalink to &quot;Step 3: Run the Scan&quot;">​</a></h3><ol><li>Click <strong>Scan</strong> button</li><li>Wait for analysis (may take a few seconds for large projects)</li><li>Results appear in the table view</li></ol><h3 id="step-4-review-duplicates" tabindex="-1">Step 4: Review Duplicates <a class="header-anchor" href="#step-4-review-duplicates" aria-label="Permalink to &quot;Step 4: Review Duplicates&quot;">​</a></h3><p>For each duplicate pair:</p><ul><li><strong>Thumbnails</strong> show visual preview</li><li><strong>Size</strong> column shows wasted disk space</li><li><strong>Dependencies</strong> shows how many assets use it</li><li><strong>Referencers</strong> shows where it&#39;s used</li></ul><p>Click any row to see detailed information.</p><h3 id="step-5-clean-up-duplicates" tabindex="-1">Step 5: Clean Up Duplicates <a class="header-anchor" href="#step-5-clean-up-duplicates" aria-label="Permalink to &quot;Step 5: Clean Up Duplicates&quot;">​</a></h3><p><strong>Redirect &amp; Delete (Recommended):</strong></p><ol><li>Select duplicates you want to remove</li><li>Click <strong>Redirect &amp; Delete</strong></li><li>Confirm the operation</li><li>All references are automatically updated</li></ol><p><strong>Delete Only (Advanced):</strong></p><ol><li>Select duplicates</li><li>Click <strong>Delete Only</strong></li><li>Use only if you&#39;ve manually updated references</li></ol><h2 id="common-workflows" tabindex="-1">Common Workflows <a class="header-anchor" href="#common-workflows" aria-label="Permalink to &quot;Common Workflows&quot;">​</a></h2><h3 id="full-project-cleanup" tabindex="-1">Full Project Cleanup <a class="header-anchor" href="#full-project-cleanup" aria-label="Permalink to &quot;Full Project Cleanup&quot;">​</a></h3><p>Perfect for periodic maintenance:</p><ol><li>Open Duplicate Asset Detector from Tools menu</li><li>Keep default settings</li><li>Click <strong>Scan All Assets</strong></li><li>Review results by size (largest first)</li><li>Select all or batch-select duplicates</li><li>Click <strong>Redirect &amp; Delete</strong></li><li>Export report for documentation</li></ol><h3 id="folder-specific-cleanup" tabindex="-1">Folder-Specific Cleanup <a class="header-anchor" href="#folder-specific-cleanup" aria-label="Permalink to &quot;Folder-Specific Cleanup&quot;">​</a></h3><p>When working on specific areas:</p><ol><li>Right-click folder in Content Browser</li><li>Select <strong>Find Duplicates</strong></li><li>Review folder-specific results</li><li>Clean up duplicates in that folder</li><li>Continue with next folder</li></ol><h3 id="pre-build-optimization" tabindex="-1">Pre-Build Optimization <a class="header-anchor" href="#pre-build-optimization" aria-label="Permalink to &quot;Pre-Build Optimization&quot;">​</a></h3><p>Before shipping:</p><ol><li>Run full project scan</li><li>Export report to CSV</li><li>Review with team</li><li>Clean up largest duplicates first</li><li>Document savings in build notes</li></ol><h2 id="tips-best-practices" tabindex="-1">Tips &amp; Best Practices <a class="header-anchor" href="#tips-best-practices" aria-label="Permalink to &quot;Tips &amp; Best Practices&quot;">​</a></h2><h3 id="before-large-cleanups" tabindex="-1">Before Large Cleanups <a class="header-anchor" href="#before-large-cleanups" aria-label="Permalink to &quot;Before Large Cleanups&quot;">​</a></h3><p>✅ <strong>Do:</strong></p><ul><li>Backup your project</li><li>Close all open levels</li><li>Run a full scan first</li><li>Export report for reference</li><li>Clean up largest duplicates first</li></ul><p>❌ <strong>Don&#39;t:</strong></p><ul><li>Clean up duplicates with many referencers without review</li><li>Delete assets currently in use in open levels</li><li>Skip the preview step</li></ul><h3 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h3><ul><li>First scan may take longer (building asset database)</li><li>Subsequent scans are much faster</li><li>Filter by asset type to speed up targeted scans</li><li>Use folder scans for incremental cleanup</li></ul><h3 id="team-workflows" tabindex="-1">Team Workflows <a class="header-anchor" href="#team-workflows" aria-label="Permalink to &quot;Team Workflows&quot;">​</a></h3><ol><li><strong>Weekly Scans:</strong> Run automated scans and export reports</li><li><strong>Review Reports:</strong> Discuss with team before cleanup</li><li><strong>Incremental Cleanup:</strong> Clean up folder-by-folder</li><li><strong>Document Changes:</strong> Keep cleanup logs for reference</li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="asset-is-already-in-use-warning" tabindex="-1">&quot;Asset is already in use&quot; Warning <a class="header-anchor" href="#asset-is-already-in-use-warning" aria-label="Permalink to &quot;&quot;Asset is already in use&quot; Warning&quot;">​</a></h3><p><strong>Cause:</strong> Asset is currently used in an open level</p><p><strong>Solution:</strong></p><ul><li>Close the level before deletion</li><li>Or reload project after redirect operation</li></ul><h3 id="false-positive-detected" tabindex="-1">False Positive Detected <a class="header-anchor" href="#false-positive-detected" aria-label="Permalink to &quot;False Positive Detected&quot;">​</a></h3><p><strong>Cause:</strong> Rare edge cases with complex assets</p><p><strong>Solution:</strong></p><ul><li>Report the issue through the <a href="https://deblx.com/help" target="_blank" rel="noreferrer">Deblx Help Center</a> or Discord</li><li>Exclude the specific asset from cleanup</li></ul><h3 id="scan-takes-too-long" tabindex="-1">Scan Takes Too Long <a class="header-anchor" href="#scan-takes-too-long" aria-label="Permalink to &quot;Scan Takes Too Long&quot;">​</a></h3><p><strong>Cause:</strong> Very large project (100,000+ assets)</p><p><strong>Solution:</strong></p><ul><li>Scan specific folders instead of entire project</li><li>Filter by asset type</li><li>Exclude Engine/Plugin content</li></ul>',57)])])}const g=t(o,[["render",s]]);export{h as __pageData,g as default};
